// Radiographer worklist (STAT first, then by due time)  (permissions: imaging.order.update)
export const worklistImaging = () =>
  api("GET", `/imaging/worklist`, undefined);   // api(): see get_guide('envelope-and-errors')

// Progress / cancel an imaging order  (permissions: imaging.order.update)
export const setStatusImagingOrders = (order_id, body) =>
  api("POST", `/imaging/orders/${order_id}/status`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// Link the PACS study (auto-find by accession if no ids given)  (permissions: imaging.order.update)
export const linkStudy = (order_id, body) =>
  api("POST", `/imaging/orders/${order_id}/link-study`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// Enter the radiology report (radiologist)  (permissions: imaging.report.enter)
export const reportImagingOrders = (order_id, body) =>
  api("POST", `/imaging/orders/${order_id}/report`, body, { idempotent: true });   // api(): see get_guide('envelope-and-errors')

// Imaging order with viewer URL  (permissions: imaging.order.view)
export const getOrder = (order_id) =>
  api("GET", `/imaging/orders/${order_id}`, undefined);   // api(): see get_guide('envelope-and-errors')

// The critical imaging findings list  (permissions: imaging.report.enter, diagnostics.setup.manage, diagnostics.critical.view)
export const listFindings = () =>
  api("GET", `/critical-imaging-findings`, undefined);   // api(): see get_guide('envelope-and-errors')

// Scan to verify a patient's identity  (permissions: patient.view)
export const verifyWristband = () =>
  api("GET", `/wristbands/verify`, undefined);   // api(): see get_guide('envelope-and-errors')

// Printable radiology report with the reporter's stamp  (permissions: imaging.order.view)
export const reportPrintImagingOrdersPayload = (order_id) =>
  api("GET", `/imaging/orders/${order_id}/report/print-payload`, undefined);   // api(): see get_guide('envelope-and-errors')

// The radiology report as a PDF  (permissions: imaging.order.view)
export const reportPdfImagingOrders = (order_id) =>
  api("GET", `/imaging/orders/${order_id}/report/pdf`, undefined);   // api(): see get_guide('envelope-and-errors')
